const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
const lastSeen = new Int32Array(100001);
let left = 1;
let best = 0;

for (let i = 1; i <= n; i++) {
  const value = data[i];
  if (lastSeen[value] >= left) {
    left = lastSeen[value] + 1;
  }
  lastSeen[value] = i;
  best = Math.max(best, i - left + 1);
}

console.log(best);
